import displayData from "./species-display.json";

/** Display names (Italian and English) generated by scripts/fetch-species.ts. */
export interface DisplayNames {
  it: string;
  en: string;
}

interface DisplayFile {
  species: Record<string, DisplayNames>;
  abilities: Record<string, DisplayNames>;
  items: Record<string, DisplayNames>;
}

const data = displayData as DisplayFile;

/** Species display names, by national dex number. */
export function speciesName(id: number, lang: keyof DisplayNames = "en"): string {
  return data.species[id]?.[lang] ?? `#${id}`;
}

/** Ability display names, by in-game ability index. */
export function abilityName(id: number, lang: keyof DisplayNames = "en"): string {
  return data.abilities[id]?.[lang] ?? `#${id}`;
}

/** Item display names, by Generation IV item index. */
export function itemName(id: number, lang: keyof DisplayNames = "en"): string {
  return data.items[id]?.[lang] ?? `#${id}`;
}

/** The full display table, for passing to the client island as props. */
export function displayTable(): DisplayFile {
  return data;
}

export type { DisplayFile };

export { spriteUrl } from "./sprites";
